package com.example.melonstools.data;

import com.example.melonstools.department.DepartmentPolicy;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.ListTag;
import net.minecraft.nbt.Tag;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.level.saveddata.SavedData;

import java.util.*;

/** Approved-application-bound facility fund payments. */
public class FacilityPaymentSavedData extends SavedData {
    public static final String DATA_NAME = "melon_facility_payments";
    public static final String PENDING="pending", APPROVED="approved", PAID="paid", FAILED="failed", CANCELLED="cancelled";
    public static final long LOW_VALUE_LIMIT=1000L, FACILITY_REVIEW_LIMIT=10000L;
    private final List<Payment> payments = new ArrayList<>(); private int sequence;
    public static FacilityPaymentSavedData get(ServerLevel l){return l.getDataStorage().computeIfAbsent(FacilityPaymentSavedData::load, FacilityPaymentSavedData::new, DATA_NAME);} 
    public static FacilityPaymentSavedData load(CompoundTag tag){FacilityPaymentSavedData d=new FacilityPaymentSavedData(); d.sequence=tag.getInt("Sequence"); ListTag a=tag.getList("Payments", Tag.TAG_COMPOUND); for(int i=0;i<a.size();i++)d.payments.add(Payment.load(a.getCompound(i))); return d;}
    @Override public CompoundTag save(CompoundTag tag){tag.putInt("Sequence",sequence); ListTag a=new ListTag(); for(Payment p:payments)a.add(p.save()); tag.put("Payments",a); return tag;}
    public List<Payment> payments(){return Collections.unmodifiableList(payments);} public Payment find(String id){for(Payment p:payments)if(p.id.equals(id))return p;return null;}

    public Payment create(ServerPlayer actor, JsonObject o){
        if(actor==null)return null; String source=get(o,"sourceApplicationId","");
        Payment p=new Payment(); p.id="fac-pay-"+(++sequence); p.status=PENDING; p.sourceApplicationId=source; p.payeeUuid=get(o,"payeeUuid",get(o,"uuid","")); p.payeeName=get(o,"payeeName",get(o,"target", "")); p.amount=Math.max(0L,getLong(o,"amount",0L)); p.riskLevel=normalizeRisk(get(o,"riskLevel",get(o,"risk","low"))); p.reason=get(o,"reason",get(o,"note","")); p.requesterUuid=actor.getUUID().toString(); p.requesterName=actor.getScoreboardName(); p.createdAt=p.updatedAt=System.currentTimeMillis();
        boolean valid=isApprovedSource(DepartmentApplicationSavedData.get(actor.serverLevel()).find(source))&&p.amount>0;
        if(!valid)p.status=FAILED; payments.add(p); setDirty();
        OperationAuditSavedData.get(actor.serverLevel()).record(actor,"facility_payment_create",p.id,valid?"ok":"denied","sourceApplicationId="+source,"",p.status); return p;
    }
    public boolean approve(String id, ServerPlayer actor, String note){Payment p=find(id); if(p==null||actor==null||!PENDING.equals(p.status))return false; boolean ok=canApprove(actor,p); if(ok){p.status=APPROVED;p.approverChain=append(p.approverChain,actor.getScoreboardName()+":"+routeFor(p));p.approvedAt=p.updatedAt=System.currentTimeMillis();setDirty();} audit(actor,"facility_payment_approve",p,ok,note); return ok;}
    public boolean pay(String id, ServerPlayer actor, String note){Payment p=find(id); if(p==null||actor==null||!APPROVED.equals(p.status))return false; boolean permitted=canExecute(actor,p); boolean ok=false; if(permitted){ok=FacilityFundManager.get(actor.serverLevel()).withdrawWithSource(p.amount,actor.getScoreboardName(),"facility_payment:"+p.id+" "+note,p.sourceApplicationId); if(ok){p.status=PAID;p.paidAt=System.currentTimeMillis();} else p.status=FAILED; p.executorUuid=actor.getUUID().toString(); p.executorName=actor.getScoreboardName(); p.updatedAt=System.currentTimeMillis(); setDirty();} audit(actor,"facility_payment_pay",p,permitted&&ok,permitted?"atomic_withdraw;"+note:"permission_denied"); return permitted&&ok;}
    public boolean cancel(String id, ServerPlayer actor, String reason){Payment p=find(id); if(p==null||actor==null||PAID.equals(p.status)||FAILED.equals(p.status)||CANCELLED.equals(p.status))return false; boolean ok=p.requesterUuid.equals(actor.getUUID().toString())||canApprove(actor,p); if(ok){p.status=CANCELLED;p.updatedAt=System.currentTimeMillis();setDirty();} audit(actor,"facility_payment_cancel",p,ok,reason); return ok;}
    public JsonObject toJsonFor(ServerPlayer viewer){JsonObject root=new JsonObject(); JsonArray a=new JsonArray(); for(Payment p:payments)a.add(p.toJson()); root.add("items",a); root.addProperty("stateMachine","pending->approved->paid/failed/cancelled"); root.addProperty("rule","sourceApplicationId must exist and be approved/card_change_required/completed; pay uses FacilityFundManager atomic withdraw only"); return root;}
    private boolean isApprovedSource(DepartmentApplicationSavedData.Application a){return a!=null&&(DepartmentApplicationSavedData.STATUS_APPROVED.equals(a.status)||DepartmentApplicationSavedData.STATUS_CARD_CHANGE_REQUIRED.equals(a.status)||DepartmentApplicationSavedData.STATUS_COMPLETED.equals(a.status));}
    private static boolean requiresFacility(Payment p){return p.amount>=FACILITY_REVIEW_LIMIT||"high".equalsIgnoreCase(p.riskLevel);} private static String routeFor(Payment p){return p.amount<=LOW_VALUE_LIMIT&&!requiresFacility(p)?"logistics3":(requiresFacility(p)?"logistics4+facility5":"logistics4");}
    private static boolean canApprove(ServerPlayer a,Payment p){DepartmentPolicy.Identity id=DepartmentPolicy.identity(a); if(a.hasPermissions(2)||DepartmentPolicy.isFacilityDirector(id.department(),id.position(),id.level()))return true; if(requiresFacility(p))return false; if(p.amount<=LOW_VALUE_LIMIT)return DepartmentPolicy.DEPT_LOGISTICS.equals(id.department())&&id.level()>=3; return DepartmentPolicy.isLogisticsSupervisor(id.department(),id.position(),id.level());}
    private static boolean canExecute(ServerPlayer a,Payment p){DepartmentPolicy.Identity id=DepartmentPolicy.identity(a); if(a.hasPermissions(2)||DepartmentPolicy.isFacilityDirector(id.department(),id.position(),id.level()))return true; if(requiresFacility(p))return false; if(p.amount<=LOW_VALUE_LIMIT)return DepartmentPolicy.DEPT_LOGISTICS.equals(id.department())&&id.level()>=3; return DepartmentPolicy.isLogisticsSupervisor(id.department(),id.position(),id.level());}
    private void audit(ServerPlayer a,String act,Payment p,boolean ok,String note){OperationAuditSavedData.get(a.serverLevel()).record(a,act,p==null?"":p.id,ok?"ok":"denied",note,"",p==null?"":p.status);} private static String append(String a,String b){return (a==null||a.isBlank())?b:a+">"+b;} private static String normalizeRisk(String r){return "high".equalsIgnoreCase(r)||"高".equals(r)?"high":"low";} private static String get(JsonObject o,String k,String d){return o!=null&&o.has(k)&&!o.get(k).isJsonNull()?o.get(k).getAsString():d;} private static long getLong(JsonObject o,String k,long d){try{return o!=null&&o.has(k)?o.get(k).getAsLong():d;}catch(Throwable t){return d;}}

    public static class Payment{public String id="",status=PENDING,sourceApplicationId="",payeeUuid="",payeeName="",requesterUuid="",requesterName="",approverChain="",executorUuid="",executorName="",reason="",riskLevel="low"; public long amount,createdAt,updatedAt,approvedAt,paidAt; CompoundTag save(){CompoundTag t=new CompoundTag(); t.putString("Id",id);t.putString("Status",status);t.putString("SourceApplicationId",sourceApplicationId);t.putString("PayeeUuid",payeeUuid);t.putString("PayeeName",payeeName);t.putLong("Amount",amount);t.putString("RequesterUuid",requesterUuid);t.putString("RequesterName",requesterName);t.putString("ApproverChain",approverChain);t.putString("ExecutorUuid",executorUuid);t.putString("ExecutorName",executorName);t.putString("Reason",reason);t.putString("RiskLevel",riskLevel);t.putLong("CreatedAt",createdAt);t.putLong("UpdatedAt",updatedAt);t.putLong("ApprovedAt",approvedAt);t.putLong("PaidAt",paidAt);return t;} static Payment load(CompoundTag t){Payment p=new Payment();p.id=t.getString("Id");p.status=t.getString("Status");p.sourceApplicationId=t.getString("SourceApplicationId");p.payeeUuid=t.getString("PayeeUuid");p.payeeName=t.getString("PayeeName");p.amount=t.getLong("Amount");p.requesterUuid=t.getString("RequesterUuid");p.requesterName=t.getString("RequesterName");p.approverChain=t.getString("ApproverChain");p.executorUuid=t.getString("ExecutorUuid");p.executorName=t.getString("ExecutorName");p.reason=t.getString("Reason");p.riskLevel=t.getString("RiskLevel");if(p.riskLevel.isBlank())p.riskLevel="low";p.createdAt=t.getLong("CreatedAt");p.updatedAt=t.getLong("UpdatedAt");p.approvedAt=t.getLong("ApprovedAt");p.paidAt=t.getLong("PaidAt");return p;} JsonObject toJson(){JsonObject o=new JsonObject();o.addProperty("id",id);o.addProperty("status",status);o.addProperty("sourceApplicationId",sourceApplicationId);o.addProperty("payeeUuid",payeeUuid);o.addProperty("payeeName",payeeName);o.addProperty("amount",amount);o.addProperty("requesterUuid",requesterUuid);o.addProperty("requesterName",requesterName);o.addProperty("approverChain",approverChain);o.addProperty("executorUuid",executorUuid);o.addProperty("executorName",executorName);o.addProperty("reason",reason);o.addProperty("riskLevel",riskLevel);o.addProperty("createdAt",createdAt);o.addProperty("updatedAt",updatedAt);o.addProperty("approvedAt",approvedAt);o.addProperty("paidAt",paidAt);return o;}}
}
